157	/// POST /datasets/records：整体成功或整体失败的批量写入。
158	async fn write_records(
159	    State(state): State<AppState>,
160	    body: Bytes,
161	) -> Result<Json<WriteResponse>, (StatusCode, Json<ErrorBody>)> {
162	    // 解析与全部校验都在锁外完成；只有整批合法时才持锁一次性提交。
163	    let parsed: WriteRequest = serde_json::from_slice(&body)
164	        .map_err(|e| bad_request(format!("请求必须是包含 records 数组的 JSON 对象: {e}")))?;
165	
166	    if parsed.records.is_empty() {
167	        return Err(bad_request("records 不能为空批次"));
168	    }
169	
170	    let mut seen = HashSet::with_capacity(parsed.records.len());
171	    let mut batch: Vec<(String, Fields)> = Vec::with_capacity(parsed.records.len());
172	
173	    for (index, record) in parsed.records.into_iter().enumerate() {
174	        let fail = |message: &'static str| {
175	            (
176	                StatusCode::BAD_REQUEST,
177	                Json(ErrorBody {
178	                    error: message.to_owned(),
179	                    index: Some(index),
180	                }),
181	            )
182	        };
183	
184	        let mut object = match record {
185	            Value::Object(map) => map,
186	            _ => return Err(fail("每条记录必须是 JSON 对象")),
187	        };
188	
189	        let key = match object.remove("key") {
190	            Some(Value::String(key)) => key,
191	            Some(_) => return Err(fail("记录的 key 必须是字符串")),
192	            None => return Err(fail("记录缺少键 key")),
193	        };
194	
195	        let fields = match object.remove("fields") {
196	            Some(Value::Object(fields)) => fields,
197	            Some(_) => return Err(fail("记录的 fields 必须是 JSON 对象")),
198	            None => return Err(fail("记录缺少字段集 fields")),
199	        };
200	
201	        if !seen.insert(key.clone()) {
202	            return Err((
203	                StatusCode::CONFLICT,
204	                Json(ErrorBody {
205	                    error: format!("批次内出现重复键: {key}"),
206	                    index: Some(index),
207	                }),
208	            ));
209	        }
210	
211	        batch.push((key, fields));
212	    }
213	
214	    // 全部合法：持锁整体覆盖写入。任一条非法都在上面提前返回，数据集保持原状。
215	    let mut store = state.store.lock().unwrap();
216	    let written = batch.len();
217	    for (key, fields) in batch {
218	        store.dataset.insert(key, fields);
219	    }
220	    Ok(Json(WriteResponse {
221	        written,
222	        total: store.dataset.len(),
223	    }))
224	}
225	
226	/// POST /versions：把当前数据集固化为不可变快照。
227	async fn save_version(State(state): State<AppState>) -> Json<SaveResponse> {
228	    let mut store: MutexGuard<Store> = state.store.lock().unwrap();
229	    let version = store.snapshots.len() as u64 + 1;
230	    let records = store
231	        .dataset
232	        .iter()
233	        .map(|(key, fields)| (key.clone(), Value::Object(fields.clone())))
234	        .collect();
235	    let total = store.dataset.len();
236	    store.snapshots.push(Snapshot { version, records });
237	    Json(SaveResponse { version, total })
238	}
239	
240	/// GET /snapshots?version=N[&key=K]：读取历史快照。
241	async fn get_snapshot(
242	    State(state): State<AppState>,
243	    req: Request,
244	) -> Result<axum::response::Response, (StatusCode, Json<ErrorBody>)> {
245	    let params = parse_snapshot_query(req.uri()).map_err(bad_request)?;
246	
247	    let store = state.store.lock().unwrap();
248	    let snapshot = store
249	        .snapshots
250	        .iter()
251	        .find(|s| s.version == params.version)
252	        .cloned()
253	        .ok_or_else(|| {
254	            (
255	                StatusCode::NOT_FOUND,
256	                Json(ErrorBody {
257	                    error: format!("版本 {} 不存在或尚未保存", params.version),
258	                    index: None,
259	                }),
260	            )
261	        })?;
262	
263	    match params.key {
264	        Some(key) => {
265	            let fields = snapshot.records.get(&key).cloned().ok_or_else(|| {
266	                (
267	                    StatusCode::NOT_FOUND,
268	                    Json(ErrorBody {
269	                        error: format!("版本 {} 中不存在键 {key}", snapshot.version),
270	                        index: None,
271	                    }),
272	                )
273	            })?;
274	            Ok(Json(SnapshotRecord {
275	                version: snapshot.version,
276	                key,
277	                fields,
278	            })
279	            .into_response())
280	        }
281	        None => {
282	            // BTreeMap 的迭代顺序即键的字典序。
283	            let records = snapshot
284	                .records
285	                .into_iter()
286	                .map(|(key, fields)| RecordOut { key, fields })
287	                .collect();
288	            Ok(Json(SnapshotSummary {
289	                version: snapshot.version,
290	                records,
291	            })
292	            .into_response())
293	        }
294	    }
295	}
296	
297	#[tokio::main]
298	async fn main() -> Result<(), Box<dyn Error>> {
299	    let bind = env::var("VDE_BIND").unwrap_or_else(|_| "127.0.0.1:8080".to_owned());
300	    let listener = tokio::net::TcpListener::bind(&bind).await?;
301	    let state = AppState {
302	        store: std::sync::Arc::new(Mutex::new(Store::default())),
303	    };
304	    let app = Router::new()
305	        .route("/health", get(health))
306	        .route("/version", get(version))
307	        .route("/datasets/records", post(write_records))
308	        .route("/versions", post(save_version))
309	        .route("/snapshots", get(get_snapshot))
310	        .with_state(state);
311	
312	    println!("Listening on http://{}", listener.local_addr()?);
313	    axum::serve(listener, app)
314	        .with_graceful_shutdown(async {
315	            let _ = tokio::signal::ctrl_c().await;
316	        })
317	        .await?;
318	    Ok(())
